I'll start by creating a React component for a shopping cart with state management using Redux Toolkit. This is a common requirement for e-commerce applications.

```jsx
import { createSlice, configureStore } from '@reduxjs/toolkit';
import { useSelector, useDispatch } from 'react-redux';
import { useState } from 'react';

// Redux Slice Definition
const cartSlice = createSlice({
  name: 'cart',
  initialState: {
    items: [],
    total: 0,
    itemCount: 0,
  },
  reducers: {
    addToCart: (state, action) => {
      const item = action.payload;
      const existingItemIndex = state.items.findIndex(
        (cartItem) => cartItem.id === item.id
      );

      if (existingItemIndex !== -1) {
        state.items[existingItemIndex].quantity += 1;
      } else {
        state.items.push({ ...item, quantity: 1 });
      }

      state.itemCount += 1;
      state.total += item.price;
    },
    removeFromCart: (state, action) => {
      const itemToRemove = action.payload;
      const itemIndex = state.items.findIndex(
        (item) => item.id === itemToRemove.id
      );

      if (itemIndex !== -1) {
        const { price, quantity } = state.items[itemIndex];
        state.itemCount -= quantity;
        state.total -= price * quantity;
        state.items.splice(itemIndex, 1);
      }
    },
    updateQuantity: (state, action) => {
      const { id, newQuantity } = action.payload;
      const itemIndex = state.items.findIndex((item) => item.id === id);

      if (itemIndex !== -1) {
        const oldQuantity = state.items[itemIndex].quantity;
        const price = state.items[itemIndex].price;
        state.itemCount = state.itemCount - oldQuantity + newQuantity;
        state.total = state.total - (price * oldQuantity) + (price * newQuantity);
        state.items[itemIndex].quantity = newQuantity;
      }
    },
    clearCart: (state) => {
      state.items = [];
      state.itemCount = 0;
      state.total = 0;
    },
  },
});

